function gridMap(data,r){const grid=data.grid||[],cells=data.cells||[],size=Math.max(1,Math.round(Math.sqrt(grid.length))),step=360/Math.max(1,size-1),start=size===1?250:70;const cellText=c=>c.eligible?(c.rank??'未见'):c.attempted?'待核':'未采';const cellHref=c=>c.observationId?href('evidence',r.id,params(r,{point:c.id,observation:c.observationId})):href('store',r.id,params(r,{point:c.id}));const spec=data.gridSpec||{};const payload={kind:'grid',center:Number.isFinite(spec.center?.latitude)&&Number.isFinite(spec.center?.longitude)?{lat:spec.center.latitude,lng:spec.center.longitude}:null,radiusKm:Number.isFinite(spec.radiusKm)?spec.radiusKm:null,size,metrics:data.metrics||null,items:cells.filter(c=>Number.isFinite(c.latitude)&&Number.isFinite(c.longitude)).map(c=>({id:c.id,lat:c.latitude,lng:c.longitude,rank:c.rank,eligible:!!c.eligible,attempted:!!c.attempted,distanceKm:c.distanceKm,text:String(cellText(c)),href:cellHref(c)}))};const m=data.metrics;const metrics=m&&m.points?'<div class="map-metrics"><div><span>ARP（出现点平均名次）</span><strong>'+E(m.arp??'—')+'</strong></div><div><span>ATRP（未见计 21）</span><strong>'+E(m.atrp??'—')+'</strong></div><div><span>SoLV（Top 3 占比）</span><strong>'+(Number.isFinite(m.solv)?Math.round(m.solv*100)+'%':'—')+'</strong></div><div><span>合格点</span><strong>'+E(m.points)+'</strong></div></div>':'';const svg='<svg class="point-map" viewBox="0 0 500 490" role="img" aria-label="该次采集网格，北在上"><text x="250" y="24" text-anchor="middle">北 ↑ · '+size+' × '+size+' 采样点</text>'+cells.map((c,i)=>{const x=start+(i%size)*step,y=(size===1?240:65)+Math.floor(i/size)*step;const text=c.eligible?(c.rank??'未见'):c.attempted?'待核':'未采';const fill=c.eligible?(c.rank===null?'#fff0d3':c.rank<=3?'#dff1e7':'#eee4fb'):'#efedf4';const target=c.observationId?href('evidence',r.id,params(r,{point:c.id,observation:c.observationId})):href('store',r.id,params(r,{point:c.id}));return '<a href="'+E(target)+'" tabindex="0" aria-label="'+E(c.id+' '+text)+'"><circle cx="'+x+'" cy="'+y+'" r="23" fill="'+fill+'" stroke="'+(c.id==='r0c0'?'#6d3bd1':'#d8cce7')+'" stroke-width="'+(c.id==='r0c0'?3:1)+'"/><text class="point-text" x="'+x+'" y="'+(y+4)+'" text-anchor="middle">'+text+'</text><text x="'+x+'" y="'+(y+39)+'" text-anchor="middle">'+E(c.id==='r0c0'?'中心':c.id)+'</text></a>';}).join('')+'</svg>';return metrics+'<div class="map-host" data-map="'+E(JSON.stringify(payload))+'">'+svg+'</div><div class="map-legend"><span><span class="swatch" style="background:#2e9d5c"></span>第 1–3 名</span><span><span class="swatch" style="background:#e8b004"></span>第 4–10 名</span><span><span class="swatch" style="background:#e0652a"></span>第 11–20 名</span><span><span class="swatch" style="background:#8a8a99"></span>未见（已确认）</span><span><span class="swatch rank-pending"></span>待核</span><span><span class="swatch rank-missing"></span>未采</span><span><span class="swatch" style="background:#fff;box-shadow:0 0 0 2px #6d3bd1"></span>店址所在点（紫色外圈）</span></div><div class="map-caption">每个点是该位置的一次真实搜索；点击打开这一轮的原始截图。虚线圈为距店址 1 / 3 / 5 km 的真实距离；底图 © OpenStreetMap。</div>';}
