function geoDestination(center,km,bearing){const R=6371,d=km/R,t=bearing*Math.PI/180,a=center.latitude*Math.PI/180,b=center.longitude*Math.PI/180;const a2=Math.asin(Math.sin(a)*Math.cos(d)+Math.cos(a)*Math.sin(d)*Math.cos(t));const b2=b+Math.atan2(Math.sin(t)*Math.sin(d)*Math.cos(a),Math.cos(d)-Math.sin(a)*Math.sin(a2));return {latitude:Math.round(a2*180/Math.PI*1e7)/1e7,longitude:Math.round(((b2*180/Math.PI+540)%360-180)*1e7)/1e7};}
function geoBearing(center,p){const a=center.latitude*Math.PI/180,b=p.latitude*Math.PI/180,dl=(p.longitude-center.longitude)*Math.PI/180;const y=Math.sin(dl)*Math.cos(b),x=Math.cos(a)*Math.sin(b)-Math.sin(a)*Math.cos(b)*Math.cos(dl);return Math.round(((Math.atan2(y,x)*180/Math.PI)+360)%360);}
function settingsDraft(s){const center=s.center&&Number.isFinite(s.center.latitude)?s.center:null;const points=(s.fixedPoints||[]).map(p=>({id:p.id,label:p.label,distanceKm:p.distanceKm,bearing:center&&p.distanceKm>0?geoBearing(center,p):0,latitude:p.latitude,longitude:p.longitude,original:p}));const targets=(s.keywordTargets||[]).map(t=>({keyword:t.keyword,volume:t.sourceSearchVolumeText||'',scan:t.scanPoints?[...t.scanPoints]:null,best:Boolean(t.bestVariant),goals:Object.fromEntries(t.pointTargets.map(g=>[g.pointId,g.targetRank])),original:t}));return {points,targets};}
function defaultPoints(storeId,center){const id=storeId||'store';return [{id:id+'-center',label:'中心',distanceKm:0,bearing:0},{id:id+'-3km',label:'3公里',distanceKm:3,bearing:90},{id:id+'-5km',label:'5公里',distanceKm:5,bearing:90}].map(p=>({...p,...(center?geoDestination(center,p.distanceKm,p.bearing):{latitude:null,longitude:null}),original:null}));}
